[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)
foreach($log in @('System','Microsoft-Windows-DeviceSetupManager/Admin','Microsoft-Windows-Kernel-PnP/Configuration')) {
 try { $events=Get-WinEvent -FilterHashtable @{LogName=$log;StartTime=[datetime]'2026-09-30T17:40:00'} -MaxEvents 200 -ErrorAction Stop;[ordered]@{log=$log;events=@($events | Select-Object TimeCreated,Id,ProviderName,Message)} | ConvertTo-Json -Depth 5 -Compress }
 catch { [ordered]@{log=$log;error=$_.Exception.Message} | ConvertTo-Json -Compress }
}
